namespace ghidra.app.plugin.core.analysis;



using ghidra.app.services;
using ghidra.app.util.bin.format.swift;
using ghidra.app.util.importer;
using ghidra.app.util.sourcelanguage;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;

public class SwiftTypeMetadataAnalyzer : AbstractAnalyzer {

	private static readonly string NAME = "Swift Type Metadata Analyzer";
	private static readonly string DESCRIPTION = "Discovers Swift type metadata records.";

	private SwiftTypeMetadata typeMetadata;

	public SwiftTypeMetadataAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setDefaultEnablement(true);
		setPriority(AnalysisPriority.FORMAT_ANALYSIS);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return program.getSourceLanguageIDs().contains(SwiftSourceLanguage.SWIFT_ID);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		if (typeMetadata != null) {
			return true;
		}
		try {
			typeMetadata = new SwiftTypeMetadata(program, monitor, log);
			typeMetadata.markup();
		}
		catch (IOException e) {
			return false;
		}
		return true;
	}

	/* @Override */
	public void analysisEnded(Program program) {
		typeMetadata = null;
	}
}
